import React, { useState, useEffect, useRef } from 'react';
import { getAlertConfig, updateAlertConfig, getSettings, updateSettings } from '../services/api';
import alertSound from '../utils/alertSound';

const CLASS_ICONS = {
  Normal:   '🛡️',
  Phone:    '📱',
  Medical_Mask: '😷',
  Fire:     '🔥',
  Smoke:    '💨',
  Gun:      '🔫',
  Knife:    '🔪',
  Falling:  '🏃',
  Violence: '⚡',
  Theft_Mask:  '🎭'
};
const CLASS_COLORS = {
  Normal:       '#22c55e', Phone:        '#60a5fa',
  Medical_Mask: '#34d399', Fire:         '#fb923c',
  Smoke:        '#94a3b8', Gun:          '#f87171',
  Knife:        '#facc15', Falling:      '#a78bfa',
  Violence:     '#f43f5e', Theft_Mask:   '#fbbf24'
};

export default function SettingsPage() {
  const [alertConfig,   setAlertConfig]   = useState(null);
  const [sysSettings,   setSysSettings]   = useState(null);
  const [soundSettings, setSoundSettings] = useState(alertSound.settings);
  const [saving,        setSaving]        = useState('');
  const [saved,         setSaved]         = useState('');
  const [testing,       setTesting]       = useState(false);
  const fileRef = useRef(null);

  useEffect(() => {
    loadAll();
  }, []);

  const loadAll = async () => {
    try {
      const [cfgRes, sysRes] = await Promise.all([
        getAlertConfig(),
        getSettings()
      ]);
      setAlertConfig(cfgRes.data.config   || {});
      setSysSettings(sysRes.data.settings || {});
    } catch (err) {
      console.warn('[Settings] Load failed:', err);
    }
  };

  const showSaved = (key) => {
    setSaved(key);
    setTimeout(() => setSaved(''), 2000);
  };

  // ── Save alert class config ───────────────────────────────────
  const saveAlertConfig = async () => {
    setSaving('alert');
    try {
      await updateAlertConfig(alertConfig);
      showSaved('alert');
    } catch (err) {
      console.warn('[Settings] Save alert config failed:', err);
    } finally {
      setSaving('');
    }
  };

  // ── Save system settings ──────────────────────────────────────
  const saveSysSettings = async () => {
    setSaving('sys');
    try {
      await updateSettings(sysSettings);
      showSaved('sys');
    } catch (err) {
      console.warn('[Settings] Save sys settings failed:', err);
    } finally {
      setSaving('');
    }
  };

  // ── Save sound settings ───────────────────────────────────────
  const saveSoundSettings = () => {
    alertSound.saveSettings(soundSettings);
    showSaved('sound');
  };

  // ── Test sound ────────────────────────────────────────────────
  const testSound = (type) => {
    setTesting(true);
    alertSound.test(type || soundSettings.soundType);
    setTimeout(() => setTesting(false), 3000);
  };

  // ── Load custom sound file ────────────────────────────────────
  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    try {
      await alertSound.loadCustomFile(file);
      setSoundSettings(prev => ({
        ...prev,
        soundType:  'custom',
        customFile: file.name
      }));
    } catch (err) {
      alert('Failed to load audio file. Use MP3 or WAV.');
    }
  };

  const sectionStyle = {
    background:   '#151d2e',
    border:       '1px solid #1e2d47',
    borderRadius: 8,
    padding:      16,
    marginBottom: 14
  };

  const sectionTitle = {
    fontSize:      13,
    fontWeight:    700,
    color:         '#e2e8f0',
    marginBottom:  12,
    paddingBottom: 8,
    borderBottom:  '1px solid #1e2d47',
    display:       'flex',
    alignItems:    'center',
    gap:           8
  };

  const rowStyle = {
    display:        'flex',
    justifyContent: 'space-between',
    alignItems:     'center',
    padding:        '8px 0',
    borderBottom:   '1px solid #1e2d4740'
  };

  const labelStyle = {
    fontSize: 12,
    color:    '#94a3b8'
  };

  const inputStyle = {
    background:   '#0a0e1a',
    border:       '1px solid #1e2d47',
    borderRadius: 5,
    padding:      '5px 10px',
    color:        '#e2e8f0',
    fontSize:     12,
    outline:      'none',
    width:        100
  };

  const saveBtn = (key, onClick) => ({
    background:   saved === key ? '#0d2010' : saving === key ? '#1e2d47' : '#3b82f6',
    border:       saved === key ? '1px solid #166534' : 'none',
    color:        saved === key ? '#4ade80' : saving === key ? '#64748b' : '#fff',
    padding:      '7px 18px',
    borderRadius: 6,
    fontSize:     11,
    fontWeight:   700,
    cursor:       saving === key ? 'not-allowed' : 'pointer',
    marginTop:    12
  });

  if (!alertConfig || !sysSettings) {
    return (
      <div style={{
        flex: 1, display: 'flex',
        alignItems: 'center', justifyContent: 'center',
        color: '#64748b'
      }}>
        Loading settings...
      </div>
    );
  }

  return (
    <div style={{ padding: '14px 16px', height: '100%', overflowY: 'auto' }}>

      {/* Header */}
      <div style={{ marginBottom: 16 }}>
        <h2 style={{ fontSize: 16, fontWeight: 700, color: '#fff', margin: 0 }}>
          Settings
        </h2>
        <p style={{ fontSize: 11, color: '#64748b', margin: '3px 0 0' }}>
          Configure system behavior, alerts, and notifications
        </p>
      </div>

      {/* ── 1. Recording Settings ─────────────────────────────── */}
      <div style={sectionStyle}>
        <div style={sectionTitle}>
          🎬 Recording Settings
        </div>

        {[
          { label: 'Pre-Event Recording',  key: 'pre_event_minutes',    unit: 'min', min: 1,   max: 30,  step: 1   },
          { label: 'Post-Event Recording', key: 'post_event_minutes',   unit: 'min', min: 1,   max: 30,  step: 1   },
          { label: 'Segment Duration',     key: 'segment_minutes',      unit: 'min', min: 1,   max: 60,  step: 1   },
          { label: 'Confidence Threshold', key: 'confidence_threshold', unit: '',   min: 0.1, max: 1.0, step: 0.05 },
        ].map((row, i) => (
          <div key={i} style={rowStyle}>
            <span style={labelStyle}>{row.label}</span>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <input
                type="range"
                min={row.min} max={row.max} step={row.step}
                value={sysSettings[row.key] || row.min}
                onChange={e => setSysSettings(prev => ({
                  ...prev,
                  [row.key]: row.step < 1
                    ? parseFloat(e.target.value)
                    : parseInt(e.target.value)
                }))}
                style={{ width: 120 }}
              />
              <span style={{
                fontSize: 12, fontWeight: 700,
                color: '#60a5fa', minWidth: 50
              }}>
                {sysSettings[row.key]}{row.unit}
              </span>
            </div>
          </div>
        ))}

        <button
          onClick={saveSysSettings}
          style={saveBtn('sys', saveSysSettings)}
        >
          {saved === 'sys' ? '✓ Saved!' : saving === 'sys' ? 'Saving...' : 'Save Recording Settings'}
        </button>
      </div>

      {/* ── 2. Alert Class Config ─────────────────────────────── */}
      <div style={sectionStyle}>
        <div style={sectionTitle}>
          🚨 Alert Classes — Enable/Disable per Class
        </div>
        <p style={{ fontSize: 11, color: '#64748b', marginBottom: 12 }}>
          Toggle which classes trigger alerts. Severity can also be changed.
        </p>

        <div style={{
          display: 'grid', gridTemplateColumns: 'repeat(2,1fr)', gap: 8
        }}>
          {Object.entries(CLASS_ICONS).map(([cls, icon]) => {
            const enabled  = alertConfig.enabled_classes?.[cls] ?? false;
            const severity = alertConfig.severity_map?.[cls]    || 'Low';
            const color    = CLASS_COLORS[cls];

            return (
              <div key={cls} style={{
                background:   enabled ? `${color}11` : '#0a0e1a',
                border:       `1px solid ${enabled ? color + '44' : '#1e2d47'}`,
                borderRadius: 8,
                padding:      '10px 12px',
                display:      'flex',
                alignItems:   'center',
                gap:          10,
                transition:   'all .2s'
              }}>
                {/* Toggle */}
                <div
                  onClick={() => setAlertConfig(prev => ({
                    ...prev,
                    enabled_classes: {
                      ...prev.enabled_classes,
                      [cls]: !enabled
                    }
                  }))}
                  style={{
                    width:        36,
                    height:       20,
                    borderRadius: 10,
                    background:   enabled ? color : '#253550',
                    position:     'relative',
                    cursor:       'pointer',
                    flexShrink:   0,
                    transition:   'background .2s'
                  }}
                >
                  <div style={{
                    position:   'absolute',
                    top:        3,
                    left:       enabled ? 18 : 3,
                    width:      14,
                    height:     14,
                    borderRadius: '50%',
                    background: '#fff',
                    transition: 'left .2s'
                  }} />
                </div>

                {/* Icon + Name */}
                <span style={{ fontSize: 16 }}>{icon}</span>
                <div style={{ flex: 1 }}>
                  <div style={{
                    fontSize: 11, fontWeight: 600,
                    color: enabled ? color : '#64748b'
                  }}>
                    {cls.replace('_', ' ')}
                  </div>
                </div>

                {/* Severity selector */}
                <select
                  value={severity}
                  onChange={e => setAlertConfig(prev => ({
                    ...prev,
                    severity_map: {
                      ...prev.severity_map,
                      [cls]: e.target.value
                    }
                  }))}
                  style={{
                    background:   '#0a0e1a',
                    border:       '1px solid #1e2d47',
                    color:        severity === 'High'   ? '#f87171' :
                                  severity === 'Medium' ? '#fbbf24' : '#4ade80',
                    fontSize:     10,
                    padding:      '3px 6px',
                    borderRadius: 4,
                    outline:      'none',
                    cursor:       'pointer'
                  }}
                >
                  <option value="High">High</option>
                  <option value="Medium">Medium</option>
                  <option value="Low">Low</option>
                </select>
              </div>
            );
          })}
        </div>

        <button
          onClick={saveAlertConfig}
          style={saveBtn('alert', saveAlertConfig)}
        >
          {saved === 'alert' ? '✓ Saved!' : saving === 'alert' ? 'Saving...' : 'Save Alert Config'}
        </button>
      </div>

      {/* ── 3. Sound Settings ─────────────────────────────────── */}
      <div style={sectionStyle}>
        <div style={sectionTitle}>
          🔔 Alert Sound Settings
        </div>

        {/* Enable toggle */}
        <div style={rowStyle}>
          <span style={labelStyle}>Sound Alerts Enabled</span>
          <div
            onClick={() => setSoundSettings(prev => ({
              ...prev, enabled: !prev.enabled
            }))}
            style={{
              width: 44, height: 24, borderRadius: 12,
              background: soundSettings.enabled ? '#3b82f6' : '#253550',
              position: 'relative', cursor: 'pointer',
              transition: 'background .2s'
            }}
          >
            <div style={{
              position: 'absolute', top: 4,
              left: soundSettings.enabled ? 22 : 4,
              width: 16, height: 16, borderRadius: '50%',
              background: '#fff', transition: 'left .2s'
            }} />
          </div>
        </div>

        {/* Volume */}
        <div style={rowStyle}>
          <span style={labelStyle}>Volume</span>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <span style={{ fontSize: 12 }}>🔇</span>
            <input
              type="range" min="0" max="1" step="0.1"
              value={soundSettings.volume}
              onChange={e => setSoundSettings(prev => ({
                ...prev, volume: parseFloat(e.target.value)
              }))}
              style={{ width: 120 }}
            />
            <span style={{ fontSize: 12 }}>🔊</span>
            <span style={{
              fontSize: 12, fontWeight: 700,
              color: '#60a5fa', minWidth: 35
            }}>
              {Math.round(soundSettings.volume * 100)}%
            </span>
          </div>
        </div>

        {/* Sound Type */}
        <div style={{ ...rowStyle, alignItems: 'flex-start', paddingTop: 10 }}>
          <span style={labelStyle}>Sound Type</span>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6, alignItems: 'flex-end' }}>
            <div style={{ display: 'flex', gap: 6 }}>
              {['beep', 'alarm', 'siren', 'custom'].map(type => (
                <button
                  key={type}
                  onClick={() => setSoundSettings(prev => ({ ...prev, soundType: type }))}
                  style={{
                    background:   soundSettings.soundType === type ? '#1e3a5f' : '#0a0e1a',
                    border:       `1px solid ${soundSettings.soundType === type ? '#3b82f6' : '#1e2d47'}`,
                    color:        soundSettings.soundType === type ? '#60a5fa' : '#64748b',
                    padding:      '5px 12px',
                    borderRadius: 5,
                    fontSize:     11,
                    cursor:       'pointer',
                    fontWeight:   soundSettings.soundType === type ? 600 : 400,
                    textTransform:'capitalize'
                  }}
                >
                  {type === 'beep'   ? '🔵 Beep'  :
                   type === 'alarm'  ? '🔴 Alarm' :
                   type === 'siren'  ? '🚨 Siren' :
                   '📁 Custom'}
                </button>
              ))}
            </div>

            {/* Custom file upload */}
            {soundSettings.soundType === 'custom' && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <span style={{ fontSize: 10, color: '#64748b' }}>
                  {soundSettings.customFile || 'No file loaded'}
                </span>
                <button
                  onClick={() => fileRef.current?.click()}
                  style={{
                    background: '#1e3a5f', border: '1px solid #253550',
                    color: '#60a5fa', padding: '4px 10px',
                    borderRadius: 4, fontSize: 10, cursor: 'pointer'
                  }}
                >
                  📁 Upload Sound
                </button>
                <input
                  ref={fileRef}
                  type="file"
                  accept="audio/*"
                  style={{ display: 'none' }}
                  onChange={handleFileUpload}
                />
              </div>
            )}
          </div>
        </div>

        {/* Alert Duration */}
        <div style={rowStyle}>
          <div>
            <span style={labelStyle}>Alert Duration</span>
            <div style={{ fontSize: 10, color: '#475569', marginTop: 2 }}>
              How long to keep playing the alert
            </div>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <input
              type="range" min="5" max="120" step="5"
              value={soundSettings.duration}
              onChange={e => setSoundSettings(prev => ({
                ...prev, duration: parseInt(e.target.value)
              }))}
              style={{ width: 120 }}
            />
            <span style={{
              fontSize: 12, fontWeight: 700,
              color: '#60a5fa', minWidth: 50
            }}>
              {soundSettings.duration}s
            </span>
          </div>
        </div>

        {/* Repeat */}
        <div style={rowStyle}>
          <span style={labelStyle}>Repeat Alert</span>
          <div
            onClick={() => setSoundSettings(prev => ({
              ...prev, repeat: !prev.repeat
            }))}
            style={{
              width: 44, height: 24, borderRadius: 12,
              background: soundSettings.repeat ? '#3b82f6' : '#253550',
              position: 'relative', cursor: 'pointer',
              transition: 'background .2s'
            }}
          >
            <div style={{
              position: 'absolute', top: 4,
              left: soundSettings.repeat ? 22 : 4,
              width: 16, height: 16, borderRadius: '50%',
              background: '#fff', transition: 'left .2s'
            }} />
          </div>
        </div>

        {/* Repeat interval */}
        {soundSettings.repeat && (
          <div style={rowStyle}>
            <div>
              <span style={labelStyle}>Repeat Every</span>
              <div style={{ fontSize: 10, color: '#475569', marginTop: 2 }}>
                Interval between repeated alerts
              </div>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <input
                type="range" min="3" max="60" step="1"
                value={soundSettings.repeatInterval}
                onChange={e => setSoundSettings(prev => ({
                  ...prev, repeatInterval: parseInt(e.target.value)
                }))}
                style={{ width: 120 }}
              />
              <span style={{
                fontSize: 12, fontWeight: 700,
                color: '#60a5fa', minWidth: 50
              }}>
                {soundSettings.repeatInterval}s
              </span>
            </div>
          </div>
        )}

        {/* Test + Save buttons */}
        <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
          <button
            onClick={() => testSound()}
            disabled={testing}
            style={{
              background: testing ? '#1a2340' : '#1e3a5f',
              border:     '1px solid #253550',
              color:      testing ? '#64748b' : '#60a5fa',
              padding:    '7px 16px', borderRadius: 6,
              fontSize:   11, fontWeight: 600, cursor: 'pointer'
            }}
          >
            {testing ? '🔊 Playing...' : '▶ Test Sound'}
          </button>
          <button
            onClick={saveSoundSettings}
            style={saveBtn('sound', saveSoundSettings)}
          >
            {saved === 'sound' ? '✓ Saved!' : 'Save Sound Settings'}
          </button>
        </div>
      </div>

      {/* ── 4. Notification Settings ──────────────────────────── */}
      <div style={sectionStyle}>
        <div style={sectionTitle}>
          📧 Notification Settings
        </div>

        {/* Email */}
        <div style={{
          background: '#0a0e1a', border: '1px solid #1e2d47',
          borderRadius: 8, padding: 12, marginBottom: 10
        }}>
          <div style={{
            display: 'flex', justifyContent: 'space-between',
            alignItems: 'center', marginBottom: 10
          }}>
            <span style={{ fontSize: 12, fontWeight: 600, color: '#e2e8f0' }}>
              📧 Email Alerts
            </span>
            <div
              onClick={() => setAlertConfig(prev => ({
                ...prev, email_enabled: !prev.email_enabled
              }))}
              style={{
                width: 44, height: 24, borderRadius: 12,
                background: alertConfig.email_enabled ? '#3b82f6' : '#253550',
                position: 'relative', cursor: 'pointer',
                transition: 'background .2s'
              }}
            >
              <div style={{
                position: 'absolute', top: 4,
                left: alertConfig.email_enabled ? 22 : 4,
                width: 16, height: 16, borderRadius: '50%',
                background: '#fff', transition: 'left .2s'
              }} />
            </div>
          </div>
          {alertConfig.email_enabled && (
            <input
              placeholder="Enter email address"
              value={alertConfig.email_address || ''}
              onChange={e => setAlertConfig(prev => ({
                ...prev, email_address: e.target.value
              }))}
              style={{
                ...inputStyle, width: '100%',
                marginBottom: 0
              }}
            />
          )}
        </div>

        {/* Telegram */}
        <div style={{
          background: '#0a0e1a', border: '1px solid #1e2d47',
          borderRadius: 8, padding: 12
        }}>
          <div style={{
            display: 'flex', justifyContent: 'space-between',
            alignItems: 'center', marginBottom: 10
          }}>
            <span style={{ fontSize: 12, fontWeight: 600, color: '#e2e8f0' }}>
              ✈️ Telegram Alerts
            </span>
            <div
              onClick={() => setAlertConfig(prev => ({
                ...prev, telegram_enabled: !prev.telegram_enabled
              }))}
              style={{
                width: 44, height: 24, borderRadius: 12,
                background: alertConfig.telegram_enabled ? '#3b82f6' : '#253550',
                position: 'relative', cursor: 'pointer',
                transition: 'background .2s'
              }}
            >
              <div style={{
                position: 'absolute', top: 4,
                left: alertConfig.telegram_enabled ? 22 : 4,
                width: 16, height: 16, borderRadius: '50%',
                background: '#fff', transition: 'left .2s'
              }} />
            </div>
          </div>
          {alertConfig.telegram_enabled && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
              <input
                placeholder="Bot Token (from @BotFather)"
                value={alertConfig.telegram_token || ''}
                onChange={e => setAlertConfig(prev => ({
                  ...prev, telegram_token: e.target.value
                }))}
                style={{ ...inputStyle, width: '100%' }}
              />
              <input
                placeholder="Chat ID"
                value={alertConfig.telegram_chat_id || ''}
                onChange={e => setAlertConfig(prev => ({
                  ...prev, telegram_chat_id: e.target.value
                }))}
                style={{ ...inputStyle, width: '100%' }}
              />
            </div>
          )}
        </div>

        <button
          onClick={saveAlertConfig}
          style={saveBtn('notif', saveAlertConfig)}
        >
          {saved === 'notif' ? '✓ Saved!' : 'Save Notification Settings'}
        </button>
      </div>

    </div>
  );
}
